begin;
select no_plan();
insert into auth.users(id,email) values ('b1000000-0000-4000-8000-000000000001','suspension-admin@test.local');
insert into auth.users(id,email) values ('b1000000-0000-4000-8000-000000000002','suspension-owner@test.local');
insert into public.platform_admins(admin_email,auth_user_id) values ('suspension-admin@test.local','b1000000-0000-4000-8000-000000000001');
insert into public.artists(id,slug,display_name,email,is_public,is_verified) values ('b1000000-0000-4000-8000-000000000002','suspension-test','Suspension Test','suspension-owner@test.local',true,true);
update public.artists set published_at=now() where id='b1000000-0000-4000-8000-000000000002';
insert into public.events(id,artist_id,event_name,start_date,end_date) values ('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000002','Suspension Event',now(),now()+interval '1 day');
insert into public.online_campaigns(id,artist_id,name,slug,opens_at,closes_at) values ('b4000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000002','Suspension Campaign','suspension',now(),now()+interval '1 day');
insert into public.orders(id,event_id,order_type,total_price,customer_name,customer_email,pickup_code) values ('b3000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','preorder',100,'Test buyer','buyer@test.local','SUS123');
insert into public.queues(id,artist_id,event_id,queue_number,status,queue_service_date) values ('b5000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000002','b2000000-0000-4000-8000-000000000001',1,'waiting',current_date);
set local role anon;
select throws_ok($$select public.set_store_suspension('b1000000-0000-4000-8000-000000000002',true,false,'Support reason')$$,'42501',null,'anonymous cannot suspend');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000002","email":"suspension-owner@test.local"}',true);
select throws_ok($$select public.set_store_suspension('b1000000-0000-4000-8000-000000000002',true,false,'Support reason')$$,'P0001','forbidden','store owner denied');
select throws_ok($$update private.store_restrictions set suspended=false$$,'42501',null,'private state protected');
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000001","email":"suspension-admin@test.local"}',true);
select throws_ok($$select public.set_store_suspension('b1000000-0000-4000-8000-000000000002',true,false,'x')$$,'P0001','invalid_request','reason required');
select is(public.set_store_suspension('b1000000-0000-4000-8000-000000000002',true,false,'Support reason'),true,'admin suspends');
select throws_ok($$select public.set_store_suspension('b1000000-0000-4000-8000-000000000002',false,false,'Support reason')$$,'P0001','state_changed','stale state rejected');
select throws_ok($$delete from private.store_restriction_audit$$,'42501',null,'audit immutable to admin client');
reset role;
select set_config('request.jwt.claims','{}',true);
set local role anon;
select is(public.get_store_suspension('b1000000-0000-4000-8000-000000000002'),true,'public notice available');
reset role;
update public.artists set published_at=null where id='b1000000-0000-4000-8000-000000000002';
set local role anon;
select is(public.get_store_suspension('b1000000-0000-4000-8000-000000000002'),false,'unpublished restriction not disclosed');
reset role;
select throws_like(format('insert into public.orders(event_id,order_type,total_price) values (%L,%L,100)','b2000000-0000-4000-8000-000000000001',kind),'store_suspended:%',kind||' blocked') from unnest(array['preorder','post_event','pos_walkin','live_queue']) kind;
select throws_like($$insert into public.orders(campaign_id,order_type,total_price) values ('b4000000-0000-4000-8000-000000000001','online_sale',100)$$,'store_suspended:%','online sale blocked');
select throws_like($$insert into public.queues(artist_id,event_id,queue_number,status) values ('b1000000-0000-4000-8000-000000000002','b2000000-0000-4000-8000-000000000001',2,'waiting')$$,'store_suspended:%','new queue blocked');
select lives_ok($$update public.orders set event_id=event_id,status='completed' where id='b3000000-0000-4000-8000-000000000001'$$,'existing order can finish, even with unchanged channel assignment');
select lives_ok($$update public.queues set artist_id=artist_id,status='serving' where id='b5000000-0000-4000-8000-000000000001'$$,'existing queue can proceed');
select is((select total_price from public.orders where id='b3000000-0000-4000-8000-000000000001'),100::numeric,'price preserved');
select is((select count(*) from private.store_restriction_audit where artist_id='b1000000-0000-4000-8000-000000000002'),1::bigint,'suspension logged once');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000001","email":"suspension-admin@test.local"}',true);
select is(public.set_store_suspension('b1000000-0000-4000-8000-000000000002',false,true,'Resolved support case'),false,'admin resumes');
reset role;
select lives_ok($$insert into public.orders(event_id,order_type,total_price) values ('b2000000-0000-4000-8000-000000000001','pos_walkin',100)$$,'new order allowed after resume');
select is((select count(*) from private.store_restriction_audit where artist_id='b1000000-0000-4000-8000-000000000002'),2::bigint,'resume also logged');
select * from finish();
rollback;
